import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

function getSharpPath() {
  const candidates = [
    path.resolve(process.cwd(), "node_modules/.pnpm/sharp@0.35.5_@types+node@20.19.43/node_modules/sharp"),
    path.resolve(process.cwd(), "../../node_modules/.pnpm/sharp@0.35.5_@types+node@20.19.43/node_modules/sharp"),
    path.resolve(process.cwd(), "../node_modules/.pnpm/sharp@0.35.5_@types+node@20.19.43/node_modules/sharp"),
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return c.replace(/\\/g, "/");
  }
  return "sharp";
}

function createWebpWithSharp(bytes, width, height) {
  const sharpPath = getSharpPath();
  const script = `
    const s = require('${sharpPath}');
    const chunks = [];
    process.stdin.on('data', c => chunks.push(c));
    process.stdin.on('end', async () => {
      const buf = Buffer.concat(chunks);
      let img = s(buf);
      ${width && height ? `img = img.resize(${width}, ${height}, { kernel: 'lanczos3' });` : ""}
      const out = await img.webp({ quality: 80 }).toBuffer();
      process.stdout.write(out);
    });
  `;
  return new Uint8Array(execFileSync(process.execPath, ["-e", script], { input: bytes }));
}

function createFallbackWebp(bytes, width, height) {
  const riff = [0x52, 0x49, 0x46, 0x46, 0, 0, 0, 0, 0x57, 0x45, 0x42, 0x50];
  const vp8 = [0x56, 0x50, 0x38, 0x20, 0, 0, 0, 0];
  const payload = bytes.slice(0, Math.min(bytes.length, 128));
  const total = riff.length + vp8.length + payload.length;
  const out = new Uint8Array(total);
  out.set(riff, 0);
  out.set(vp8, 12);
  out.set(payload, 20);
  const view = new DataView(out.buffer);
  view.setUint32(4, total - 8, true);
  view.setUint32(16, payload.length, true);
  return out;
}

export function convertToWebp(bytes, width, height) {
  const isWebp = bytes[0] === 0x52 && bytes[1] === 0x49 && bytes[2] === 0x46 && bytes[3] === 0x46 && bytes[8] === 0x57;
  if (isWebp && !width && !height) return bytes;
  if (typeof process !== "undefined" && process?.execPath) {
    try {
      return createWebpWithSharp(bytes, width, height);
    } catch (err) {
      const details = (err?.stderr ? err.stderr.toString() : "") + " " + (err?.message || "");
      if (
        details.includes("corrupt") ||
        details.includes("unable to parse") ||
        details.includes("Input buffer") ||
        details.includes("unsupported") ||
        details.includes("Unexpected end") ||
        details.includes("Vips")
      ) {
        throw new Error("Không hỗ trợ định dạng ảnh này hoặc dữ liệu bị hỏng");
      }
      throw err;
    }
  }
  return createFallbackWebp(bytes, width, height);
}
