/**
 * Helper giải mã kích thước hình ảnh (PNG, JPEG, GIF, BMP, WebP) từ magic bytes.
 */
function parseJpeg(b, v) {
  let offset = 2;
  while (offset < b.length - 8) {
    if (b[offset] !== 0xff) break;
    const marker = b[offset + 1];
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      return { width: v.getUint16(offset + 7), height: v.getUint16(offset + 5) };
    }
    offset += 2 + v.getUint16(offset + 2);
  }
  return null;
}

function parseWebp(b) {
  const type = String.fromCharCode(...b.slice(12, 16));
  if (type === "VP8 " && b.length >= 30) {
    return { width: (b[27] << 8 | b[26]) & 0x3fff, height: (b[29] << 8 | b[28]) & 0x3fff };
  }
  if (type === "VP8L" && b.length >= 25 && b[20] === 0x2f) {
    const bits = b[21] | (b[22] << 8) | (b[23] << 16) | (b[24] << 24);
    return { width: (bits & 0x3fff) + 1, height: ((bits >> 14) & 0x3fff) + 1 };
  }
  if (type === "VP8X" && b.length >= 30) {
    return {
      width: 1 + (b[24] | (b[25] << 8) | (b[26] << 16)),
      height: 1 + (b[27] | (b[28] << 8) | (b[29] << 16)),
    };
  }
  return null;
}

export function getImageDimensions(bytes) {
  if (!bytes || bytes.length < 12) throw new Error("File quá nhỏ hoặc không phải định dạng ảnh");
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const v = new DataView(b.buffer, b.byteOffset, b.byteLength);

  if (b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) {
    return { width: v.getUint32(16), height: v.getUint32(20) };
  }
  if (b[0] === 0xff && b[1] === 0xd8) {
    const dim = parseJpeg(b, v);
    if (dim) return dim;
  }
  if (b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46) {
    return { width: v.getUint16(6, true), height: v.getUint16(8, true) };
  }
  if (b[0] === 0x42 && b[1] === 0x4d) {
    return { width: v.getUint32(18, true), height: Math.abs(v.getInt32(22, true)) };
  }
  if (b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b[8] === 0x57) {
    const dim = parseWebp(b);
    if (dim) return dim;
  }
  throw new Error("Không hỗ trợ định dạng ảnh này hoặc dữ liệu bị hỏng");
}
