import { getImageDimensions } from "./dimension-parser.js";
import { convertToWebp } from "./webp-converter.js";

export const SamplingFilter = {
  Nearest: 1,
  Triangle: 2,
  CatmullRom: 3,
  Gaussian: 4,
  Lanczos3: 5,
};

export class PhotonImage {
  constructor(bytes, width, height) {
    this._bytes = bytes;
    this._width = width;
    this._height = height;
    this._freed = false;
  }

  static new_from_byteslice(bytes) {
    const dim = getImageDimensions(bytes);
    return new PhotonImage(new Uint8Array(bytes), dim.width, dim.height);
  }

  get_width() {
    this._checkFreed();
    return this._width;
  }

  get_height() {
    this._checkFreed();
    return this._height;
  }

  get_bytes_webp() {
    this._checkFreed();
    return convertToWebp(this._bytes, this._width, this._height);
  }

  free() {
    this._freed = true;
    this._bytes = null;
  }

  _checkFreed() {
    if (this._freed) throw new Error("Attempt to use freed PhotonImage");
  }
}

export function resize(image, width, height, _filter) {
  image._checkFreed();
  const resizedBytes = convertToWebp(image._bytes, width, height);
  return new PhotonImage(resizedBytes, width, height);
}
